create function pg_temp.call_ntf(p int,op text,args jsonb) returns jsonb language plpgsql as $$
declare cmd jsonb:=jsonb_build_object('op','notifications.'||op,'args',args);ticket uuid;
begin perform set_config('test.actor',p::text,true);
 ticket:=public.fixture_chat_permit(p,case when op='registerDevice' then 'push' else 'chat' end,cmd);
 return public.erp_notification_center(cmd,ticket);end $$;
